import { useEffect } from "react";
import { useDataHealth as useDataHealthBase } from "../../app/use-data-health";
function useDataHealth() {
  const h = useDataHealthBase();
  const { attention } = useShell();
  useEffect(() => {
    h.retry();
  }, [attention]);
  return h;
}

import { useEffect } from "react";
import { useDataHealth as useDataHealthBase } from "../../app/use-data-health";
function useDataHealth() {
  const h = useDataHealthBase();
  useEffect(() => {
    const t = setInterval(() => h.retry(), 300000);
    return () => clearInterval(t);
  }, []);
  return h;
}

import { useEffect, useRef } from "react";
import { useDataHealth as useDataHealthBase } from "../../app/use-data-health";
function useDataHealth() {
  const h = useDataHealthBase();
  const { attention } = useShell();
  const s = attention.kind === "ok" ? (attention.data.latest_download?.state ?? null) : null;
  const prev = useRef(s);
  useEffect(() => {
    if (prev.current === "running" && s !== "running") {
      h.retry();
    }
    prev.current = s;
  }, [s]);
  return h;
}

